def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import deque

    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                (ny, nx) not in seen and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            components.append((color, comp))

    panels = []
    for color, comp in components:
        ys = [p[0] for p in comp]
        xs = [p[1] for p in comp]
        y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
        if y1 - y0 == 4 and x1 - x0 == 4 and len(comp) == 25:
            panels.append((color, y0, x0))

    out = [row[:] for row in grid]
    panel_cells = set()
    for color, y0, x0 in panels:
        for y in range(y0, y0 + 5):
            for x in range(x0, x0 + 5):
                panel_cells.add((y, x))

    # Use each isolated small same-color object as a 3x3 stamp.
    for color, comp in components:
        ys = [p[0] for p in comp]
        xs = [p[1] for p in comp]
        y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
        if y1 - y0 != 2 or x1 - x0 != 2 or len(comp) == 25:
            continue
        pattern = {(y - y0, x - x0) for y, x in comp}
        for pcolor, py, px in panels:
            if pcolor != color:
                continue
            for dy, dx in pattern:
                out[py + 1 + dy][px + 1 + dx] = bg

    if panels:
        r0 = max(0, min(y for _, y, _ in panels) - 1)
        r1 = min(h, max(y for _, y, _ in panels) + 6)
        c0 = max(0, min(x for _, _, x in panels) - 1)
        c1 = min(w, max(x for _, _, x in panels) + 6)
        return [row[c0:c1] for row in out[r0:r1]]
    return out
